SELECT INITCAP('hello sql world') AS A,
       UPPER('Sql')               AS B
  FROM DUAL;

SELECT REPLACE('2026-11-05', '-', '') AS A,
       REPLACE('ABCABC', 'B')        AS B
  FROM DUAL;

SELECT TO_DATE('2026-03-01', 'YYYY-MM-DD')
     - TO_DATE('2026-02-01', 'YYYY-MM-DD') AS DIFF
  FROM DUAL;

SELECT TO_CHAR(1234567.891, 'FM9,999,999.99') AS A,
       TO_CHAR(5, 'FM000')                AS B
  FROM DUAL;

SELECT SUBSTR('ORACLE', -4)  AS A,
       SUBSTR('SQL', 2, 10) AS B
  FROM DUAL;

SELECT INSTR('BANANA', 'AN', 1, 2) AS A,
       INSTR('BANANA', 'AN', 3)    AS B
  FROM DUAL;
